module TopModule (
    input  clk,
    input  x,
    output z
);

    // Asynchronous reset signal generated by an initial block for one cycle
    reg reset;
    initial reset = 1'b1;

    // Reset de-asserted after the first positive clock edge
    always @(posedge clk) begin
        reset <= 1'b0;
    end

    // Flip-flop outputs
    reg ff_xor, ff_and, ff_or;

    // Compute the combinational inputs to flip-flops
    wire d_xor = x ^ ff_xor;
    wire d_and = x & (~ff_and);
    wire d_or  = x | (~ff_or);

    // Flip-flops with asynchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ff_xor <= 1'b0;
            ff_and <= 1'b0;
            ff_or  <= 1'b0;
        end else begin
            ff_xor <= d_xor;
            ff_and <= d_and;
            ff_or  <= d_or;
        end
    end

    // Output is NOR of flip-flop outputs
    assign z = ~(ff_xor | ff_and | ff_or);

endmodule